//! The 55 acceptance rows of X21 (`docs/fase3/exploracion/X21_filas/`, contract F5.5), migrated to the final format in
//! `tests/data/f3g/rows/` with the oracle figures (cSlope 0.1.0) in `tests/data/f3g/expected.json` (generated by
//! `tests/data/f3g/generate.py`).
//!
//! **RED by design in wave G0.** The stubs of `crack` panic with `todo!("G1: grieta de tracción")` and the ponded
//! water adds zero terms, so:
//! - the rows with a crack (31) fail **in the stub** (panic `G1: grieta de tracción`);
//! - the rows with ponded water and no crack (20) fail **by value** (for example X21-P01: 0.848 against 0.939);
//! - the three controls (X21-N01, X21-N02 and X21-CP-V079-w000-sincrack) pass, which is the neutrality;
//! - X21-A07 (state) expects `NoValidSurface: tension_crack_not_reached` and meets the stub.
//!
//! The failing tests print the table of the rows with the form of each failure. Criteria (F5.5-3): every method within
//! 0.1 % of the oracle, with the slices that the row declares. Spencer and Morgenstern-Price are compared with the
//! same oracle figure because the oracle runs Spencer as Morgenstern-Price with `constant` (E8); each row therefore
//! declares `analysis.interslice = constant` and the methods that the oracle has for it (Bishop has none on a
//! polyline), see `tests/data/f3g/generate.py`.

use ogs_core::report::AnalysisReport;
use ogs_core::{OgsError, analyze};
use serde_json::Value;
use std::collections::BTreeMap;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::path::PathBuf;

const STUB: &str = "G1: grieta de tracción";
const TOLERANCE_PCT: f64 = 0.1;

fn data_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/data/f3g")
}

fn expected() -> Value {
    let text = std::fs::read_to_string(data_dir().join("expected.json")).expect("expected.json");
    serde_json::from_str(&text).expect("expected.json parses")
}

fn row_doc(id: &str) -> Value {
    let text = std::fs::read_to_string(data_dir().join("rows").join(format!("{id}.json")))
        .unwrap_or_else(|e| panic!("{id}: {e}"));
    serde_json::from_str(&text).expect("row parses")
}

fn row_ids(exp: &Value) -> Vec<String> {
    exp["rows"].as_object().unwrap().keys().cloned().collect()
}

/// The document of the row, as it is in `rows/`: the methods that the oracle has (the five; Bishop has none on a
/// polyline) and `analysis.interslice = constant`, so that it gives the figures of the table (E8).
fn run_doc(id: &str, _exp: &Value) -> Value {
    row_doc(id)
}

/// How a row ended.
#[derive(Debug, Clone, PartialEq)]
enum Outcome {
    Pass,
    /// The panic of the stub of G1.
    Stub,
    /// The engine analysed it, but a figure is off: the largest `|Δ|` in %, and the method.
    Value(f64, String),
    /// An error of the engine (not a panic).
    Error(String),
    /// A panic that is not the stub.
    Panic(String),
}

impl Outcome {
    fn form(&self) -> &'static str {
        match self {
            Outcome::Pass => "pass",
            Outcome::Stub => "stub",
            Outcome::Value(..) => "value",
            Outcome::Error(_) => "error",
            Outcome::Panic(_) => "panic",
        }
    }
}

/// Runs a document, catching panics: `Ok(report)`, or the error of the engine, or the panic text.
fn run_caught(doc: &Value) -> Result<AnalysisReport, Result<OgsError, String>> {
    let model = serde_json::from_value(doc.clone()).expect("a row parses as a model");
    match catch_unwind(AssertUnwindSafe(|| analyze(&model))) {
        Ok(Ok(report)) => Ok(report),
        Ok(Err(e)) => Err(Ok(e)),
        Err(payload) => Err(Err(payload
            .downcast_ref::<String>()
            .cloned()
            .or_else(|| payload.downcast_ref::<&str>().map(|s| (*s).to_string()))
            .unwrap_or_default())),
    }
}

fn method_name(m: ogs_core::model::MethodKind) -> String {
    serde_json::to_value(m)
        .unwrap()
        .as_str()
        .unwrap()
        .to_string()
}

/// `(method → fos)` of a report.
fn fos_of(report: &AnalysisReport) -> BTreeMap<String, Option<f64>> {
    report
        .results
        .iter()
        .map(|r| (method_name(r.method), r.fos))
        .collect()
}

fn judge(id: &str, exp: &Value) -> Outcome {
    let row = &exp["rows"][id];
    let result = run_caught(&run_doc(id, exp));
    if let Some(code) = row.get("expect_error").and_then(Value::as_str) {
        return match result {
            Err(Ok(OgsError::NoValidSurface(msg))) if msg.contains(code) => Outcome::Pass,
            Err(Ok(e)) => Outcome::Error(e.to_string()),
            Err(Err(p)) if p.contains(STUB) => Outcome::Stub,
            Err(Err(p)) => Outcome::Panic(p),
            Ok(_) => Outcome::Error(format!("the analysis succeeded, expected {code}")),
        };
    }
    let report = match result {
        Ok(r) => r,
        Err(Ok(e)) => return Outcome::Error(e.to_string()),
        Err(Err(p)) if p.contains(STUB) => return Outcome::Stub,
        Err(Err(p)) => return Outcome::Panic(p),
    };
    let got = fos_of(&report);
    let (mut worst, mut worst_method) = (0.0_f64, String::new());
    for (method, oracle) in row["oracle"].as_object().unwrap() {
        let oracle = oracle.as_f64().unwrap();
        let diff = match got.get(method).copied().flatten() {
            Some(fos) => (fos / oracle - 1.0).abs() * 100.0,
            None => f64::INFINITY,
        };
        if diff > worst {
            (worst, worst_method) = (diff, method.clone());
        }
    }
    if worst <= TOLERANCE_PCT {
        Outcome::Pass
    } else {
        Outcome::Value(worst, worst_method)
    }
}

/// The table of the rows, as text, and the counts per form and per kind.
fn table(outcomes: &[(String, String, Outcome)]) -> String {
    let mut counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut text = String::new();
    for (id, kind, o) in outcomes {
        *counts.entry(format!("{kind}/{}", o.form())).or_default() += 1;
        let detail = match o {
            Outcome::Pass | Outcome::Stub => String::new(),
            Outcome::Value(pct, m) if pct.is_infinite() => format!("no FS ({m})"),
            Outcome::Value(pct, m) => format!("{pct:.3} % ({m})"),
            Outcome::Error(e) | Outcome::Panic(e) => e.chars().take(110).collect(),
        };
        text.push_str(&format!("  {id:<28} {kind:<8} {:<6} {detail}\n", o.form()));
    }
    let by_form = outcomes.iter().fold(BTreeMap::new(), |mut m, (_, _, o)| {
        *m.entry(o.form()).or_insert(0usize) += 1;
        m
    });
    format!(
        "{text}by form: {by_form:?}\nby kind/form: {counts:?}\n(a row passes with every method within {TOLERANCE_PCT} % of the oracle)"
    )
}

fn judge_all(kinds: &[&str]) -> Vec<(String, String, Outcome)> {
    let exp = expected();
    row_ids(&exp)
        .into_iter()
        .filter_map(|id| {
            let kind = exp["rows"][&id]["kind"].as_str().unwrap().to_string();
            kinds.contains(&kind.as_str()).then(|| {
                let o = judge(&id, &exp);
                (id, kind, o)
            })
        })
        .collect()
}

// ------------------------------------------------------------------------------------------------ data integrity

#[test]
fn the_rows_are_the_migrated_x21_rows() {
    let exp = expected();
    let ids = row_ids(&exp);
    assert_eq!(ids.len(), 55, "54 rows with an oracle figure and X21-A07");
    let with_oracle = ids
        .iter()
        .filter(|id| {
            !exp["rows"][id.as_str()]["oracle"]
                .as_object()
                .unwrap()
                .is_empty()
        })
        .count();
    assert_eq!(with_oracle, 54);
    let kind_count = |k: &str| {
        ids.iter()
            .filter(|id| exp["rows"][id.as_str()]["kind"] == k)
            .count()
    };
    assert_eq!(
        (
            kind_count("crack"),
            kind_count("pond"),
            kind_count("control"),
            kind_count("state")
        ),
        (31, 20, 3, 1)
    );
    for id in &ids {
        let doc = row_doc(id);
        assert_eq!(doc["version"], "0.5", "{id}");
        // F5.5-3: `water.free_water` is gone and `tension_crack.water` is `water_fill`.
        assert!(doc["water"].get("free_water").is_none(), "{id}");
        if let Some(tc) = doc["analysis"].get("tension_crack") {
            assert!(
                tc.get("water").is_none() && tc["water_fill"].is_number(),
                "{id}"
            );
            assert!(
                tc["depth"] == "auto" || tc["depth"].as_f64().unwrap() > 0.0,
                "{id}"
            );
        }
        let _: ogs_core::model::Model =
            serde_json::from_value(doc).unwrap_or_else(|e| panic!("{id}: {e}"));
    }
    // The three controls are the same slope without a crack and without water over the ground.
    assert!(
        exp["rows"]["X21-N03"]["migration"]
            .to_string()
            .contains("1e-6")
    );
}

// ------------------------------------------------------------------------------------------- the oracle rows (RED)

#[test]
fn x21_rows_match_the_oracle_within_0_1_percent() {
    let outcomes = judge_all(&["crack", "pond", "control", "state"]);
    assert_eq!(outcomes.len(), 55);
    let failing = outcomes
        .iter()
        .filter(|(_, _, o)| *o != Outcome::Pass)
        .count();
    assert!(
        failing == 0,
        "{failing} of 55 rows fail (RED of wave G0)\n{}",
        table(&outcomes)
    );
}

#[test]
fn x21_controls_are_neutral() {
    // Without a crack and without water over the ground the engine is the one of v0.3.0 (E15e-1): the figures of the
    // oracle for the dry slope are reproduced, and nothing of the new code is reached.
    let outcomes = judge_all(&["control"]);
    assert_eq!(outcomes.len(), 3);
    assert!(
        outcomes.iter().all(|(_, _, o)| *o == Outcome::Pass),
        "{}",
        table(&outcomes)
    );
}

#[test]
fn x21_a07_is_discarded_with_tension_crack_not_reached() {
    // The oracle discards the surface (z = 4.24 m is deeper than the circle); the engine must too (G1).
    let exp = expected();
    let o = judge("X21-A07", &exp);
    assert_eq!(o, Outcome::Pass, "{o:?}");
}

#[test]
fn x21_crack_rows_report_where_the_crack_is() {
    // The prototype of X21 gives `x_c` and the depth that it used; the report carries them (F5.2).
    let exp = expected();
    let mut bad = Vec::new();
    for id in row_ids(&exp) {
        let Some(proto) = exp["rows"][&id].get("proto_crack") else {
            continue;
        };
        let (px, pd) = (
            proto["x"].as_f64().unwrap(),
            proto["depth"].as_f64().unwrap(),
        );
        match run_caught(&run_doc(&id, &exp)) {
            Ok(report) => {
                for r in &report.results {
                    match r.tension_crack {
                        Some(c)
                            if (c.x - px).abs() <= 1e-3 && (c.depth / pd - 1.0).abs() <= 1e-4 => {}
                        other => bad.push(format!(
                            "{id} {}: {other:?} against ({px}, {pd})",
                            method_name(r.method)
                        )),
                    }
                }
            }
            Err(Err(p)) if p.contains(STUB) => bad.push(format!("{id}: stub")),
            Err(Err(p)) => bad.push(format!("{id}: panic {p}")),
            Err(Ok(e)) => bad.push(format!("{id}: {e}")),
        }
    }
    assert!(
        bad.is_empty(),
        "{} rows without the right crack (RED of wave G0):\n{}",
        bad.len(),
        bad.iter().take(12).cloned().collect::<Vec<_>>().join("\n")
    );
}

// ----------------------------------------------------------------------------------- F5.5-4 and F5.5-5 (RED)

fn all_fos(id: &str) -> BTreeMap<String, f64> {
    let exp = expected();
    match run_caught(&run_doc(id, &exp)) {
        Ok(report) => fos_of(&report)
            .into_iter()
            .map(|(m, f)| (m, f.unwrap_or(f64::NAN)))
            .collect(),
        Err(Err(p)) => panic!("{id}: panic {p}"),
        Err(Ok(e)) => panic!("{id}: {e}"),
    }
}

#[test]
fn x21_mirror_rows_agree_to_1e_9() {
    // F5.5-4: P01/P03, D01/D03, D02/D04 and W100/W100m.
    for (a, b) in [
        ("X21-P01", "X21-P03"),
        ("X21-D01", "X21-D03"),
        ("X21-D02", "X21-D04"),
        ("X21-W100", "X21-W100m"),
    ] {
        let (fa, fb) = (all_fos(a), all_fos(b));
        assert_eq!(fa.len(), fb.len(), "{a} / {b}");
        for (m, x) in &fa {
            let y = fb[m];
            assert!((x - y).abs() <= 1e-9, "{a} / {b} {m}: {x} against {y}");
        }
    }
}

#[test]
fn x21_fs_falls_with_the_water_in_the_crack() {
    // F5.5-5: V047a (dry, 25 %, 50 %, full) and V079 (0, 25, 50, 100 %), every method.
    for chain in [
        ["X21-C20", "X21-W025", "X21-W050", "X21-W100"],
        [
            "X21-CP-V079-w000",
            "X21-CP-V079-w025",
            "X21-CP-V079-w050",
            "X21-CP-V079-w100",
        ],
    ] {
        let figures: Vec<_> = chain.iter().map(|id| all_fos(id)).collect();
        for method in figures[0].keys() {
            for (k, pair) in figures.windows(2).enumerate() {
                assert!(
                    pair[1][method] < pair[0][method],
                    "{method}: {} ({}) is not below {} ({})",
                    chain[k + 1],
                    pair[1][method],
                    chain[k],
                    pair[0][method]
                );
            }
        }
    }
}

#[test]
fn x21_fs_tends_to_the_surface_without_a_crack_as_the_depth_goes_to_zero() {
    // F5.5-5: X21-N03 has depth 1e-6 (the limit of depth -> 0+) and the same slope as X21-N01, with no crack.
    let (with, without) = (all_fos("X21-N03"), all_fos("X21-N01"));
    for (method, x) in &with {
        let y = without[method];
        assert!((x / y - 1.0).abs() <= 1e-4, "{method}: {x} against {y}");
    }
}
